CREATE TABLE writing_sessions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),section_id TEXT NOT NULL REFERENCES sections(id),operation TEXT NOT NULL,status TEXT NOT NULL,target_snapshot_id TEXT REFERENCES repository_snapshots(id),base_versions_json TEXT NOT NULL,profile_id TEXT,policy_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE writing_steps(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES writing_sessions(id),stage TEXT NOT NULL,iteration INTEGER NOT NULL,input_hash TEXT NOT NULL,state TEXT NOT NULL,lease_epoch INTEGER NOT NULL DEFAULT 0,task_id TEXT REFERENCES tasks(id),output_blob TEXT,error_json TEXT,UNIQUE(session_id,stage,iteration,input_hash));
CREATE TABLE tool_observations(id TEXT PRIMARY KEY,step_id TEXT NOT NULL REFERENCES writing_steps(id),call_id TEXT NOT NULL,tool_name TEXT NOT NULL,arguments_blob TEXT NOT NULL,result_blob TEXT NOT NULL,status TEXT NOT NULL,provenance_hash TEXT NOT NULL,egress_revision TEXT NOT NULL,UNIQUE(step_id,call_id));
CREATE TABLE writing_contexts(id TEXT PRIMARY KEY,step_id TEXT NOT NULL REFERENCES writing_steps(id),manifest_blob TEXT NOT NULL,payload_blob TEXT NOT NULL,payload_hash TEXT NOT NULL,budget_json TEXT NOT NULL,permissions_hash TEXT NOT NULL);
CREATE TABLE writing_candidates(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES writing_sessions(id),parent_candidate_id TEXT REFERENCES writing_candidates(id),document_blob TEXT NOT NULL,text_hash TEXT NOT NULL,decision_blob TEXT NOT NULL,context_id TEXT REFERENCES writing_contexts(id),created_at TEXT NOT NULL);
CREATE TABLE document_analyses(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),candidate_id TEXT REFERENCES writing_candidates(id),revision_id TEXT REFERENCES revisions(id),text_hash TEXT NOT NULL,segmenter_version TEXT NOT NULL,state TEXT NOT NULL,CHECK((candidate_id IS NOT NULL)!=(revision_id IS NOT NULL)));
CREATE TABLE sentence_spans(id TEXT PRIMARY KEY,analysis_id TEXT NOT NULL REFERENCES document_analyses(id),node_id TEXT NOT NULL,ordinal INTEGER NOT NULL,start_cp INTEGER NOT NULL,end_cp INTEGER NOT NULL,text_hash TEXT NOT NULL,role TEXT NOT NULL,CHECK(start_cp>=0 AND end_cp>start_cp),UNIQUE(analysis_id,node_id,ordinal));
CREATE TABLE sentence_claim_links(sentence_id TEXT NOT NULL REFERENCES sentence_spans(id),claim_version_id TEXT NOT NULL REFERENCES claim_versions(id),role TEXT NOT NULL,PRIMARY KEY(sentence_id,claim_version_id));
CREATE TABLE writing_verification_runs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),analysis_id TEXT REFERENCES document_analyses(id),stage TEXT NOT NULL,input_manifest_blob TEXT NOT NULL,method TEXT NOT NULL,result_blob TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE object_dependencies(project_id TEXT NOT NULL REFERENCES projects(id),upstream_type TEXT NOT NULL,upstream_id TEXT NOT NULL,upstream_version TEXT NOT NULL,downstream_type TEXT NOT NULL,downstream_id TEXT NOT NULL,downstream_version TEXT NOT NULL,relation TEXT NOT NULL,PRIMARY KEY(project_id,upstream_type,upstream_id,upstream_version,downstream_type,downstream_id,downstream_version,relation));
CREATE TABLE writing_adoptions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,candidate_id TEXT NOT NULL REFERENCES writing_candidates(id),selected_nodes_json TEXT NOT NULL,result_revision_ids_json TEXT NOT NULL,verification_manifest_blob TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,idempotency_key));
CREATE INDEX idx_writing_sessions_project ON writing_sessions(project_id,created_at);
CREATE INDEX idx_writing_verification_analysis ON writing_verification_runs(analysis_id,created_at);
